(()=>{document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll("a.footnote-backref").forEach(function(o){o.addEventListener("click",function(n){console.log("test");let t=this.getAttribute("href").replace("#",""),e=document.getElementById(t);if(e){n.preventDefault();let c=e.getBoundingClientRect().top+window.scrollY-window.innerHeight/20;window.scrollTo({top:c,behavior:"smooth"}),history.pushState(null,"","#"+t)}})})});})();
